package br.com.onda;
import android.graphics.*;import android.media.*;import android.os.SystemClock;import java.io.*;import java.nio.*;
/** Explicit still-photo movie. Two frames/second, bounded image memory, native H.264/AAC only. */
final class PhotoVideo {
 static final long FRAME_US=500000;
 static final class Pixels {final int width,height;final byte[] y,u,v;Pixels(int w,int h){width=w;height=h;y=new byte[w*h];u=new byte[w*h/4];v=new byte[w*h/4];}}
 static void create(File image,File audio,File output,DownloadMux.Cancel cancel)throws IOException{File sound=null,video=null;try{cancel.check();sound=File.createTempFile("onda-download-photo-audio-",".m4a",output.getParentFile());video=File.createTempFile("onda-download-photo-video-",".mp4",output.getParentFile());PhotoAudio.prepare(audio,sound,cancel);long duration=duration(sound);Pixels picture=pixels(image,cancel);encode(picture,duration,video,cancel);cancel.check();DownloadMux.merge(video,sound,output,false,cancel);}finally{if(sound!=null)sound.delete();if(video!=null)video.delete();}}
 static long duration(File file)throws IOException{MediaExtractor ex=new MediaExtractor();try{ex.setDataSource(file.getPath());int track=AudioTracks.select(ex);MediaFormat format=ex.getTrackFormat(track);long duration=format.containsKey(MediaFormat.KEY_DURATION)?format.getLong(MediaFormat.KEY_DURATION):0;if(duration<=0||duration>Long.MAX_VALUE-FRAME_US)throw new IOException("Não foi possível determinar a duração do áudio");return duration;}finally{ex.release();}}
 static Pixels pixels(File source,DownloadMux.Cancel cancel)throws IOException{cancel.check();Bitmap bitmap=null;try{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(source.getPath(),bounds);if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException("A foto recebida é inválida");double scale=Math.min(1d,Math.min(1280d/Math.max(bounds.outWidth,bounds.outHeight),720d/Math.min(bounds.outWidth,bounds.outHeight)));int wantedW=Math.max(2,(int)(bounds.outWidth*scale)),wantedH=Math.max(2,(int)(bounds.outHeight*scale));BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.ARGB_8888;options.inScaled=false;options.inSampleSize=1;while(bounds.outWidth/(options.inSampleSize*2)>=wantedW&&bounds.outHeight/(options.inSampleSize*2)>=wantedH)options.inSampleSize*=2;bitmap=BitmapFactory.decodeFile(source.getPath(),options);if(bitmap==null)throw new IOException("Não foi possível abrir a foto");Matrix rotation=new Matrix();try{int orientation=new ExifInterface(source.getPath()).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);switch(orientation){case ExifInterface.ORIENTATION_FLIP_HORIZONTAL:rotation.setScale(-1,1);break;case ExifInterface.ORIENTATION_ROTATE_180:rotation.setRotate(180);break;case ExifInterface.ORIENTATION_FLIP_VERTICAL:rotation.setScale(1,-1);break;case ExifInterface.ORIENTATION_TRANSPOSE:rotation.setRotate(90);rotation.postScale(-1,1);break;case ExifInterface.ORIENTATION_ROTATE_90:rotation.setRotate(90);break;case ExifInterface.ORIENTATION_TRANSVERSE:rotation.setRotate(270);rotation.postScale(-1,1);break;case ExifInterface.ORIENTATION_ROTATE_270:rotation.setRotate(270);break;}}catch(IOException ignored){}if(!rotation.isIdentity()){Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),rotation,true);if(rotated!=bitmap){bitmap.recycle();bitmap=rotated;}}scale=Math.min(1d,Math.min(1280d/Math.max(bitmap.getWidth(),bitmap.getHeight()),720d/Math.min(bitmap.getWidth(),bitmap.getHeight())));int w=Math.max(2,((int)(bitmap.getWidth()*scale))&~1),h=Math.max(2,((int)(bitmap.getHeight()*scale))&~1);Bitmap resized=Bitmap.createScaledBitmap(bitmap,w,h,true);if(resized!=bitmap){bitmap.recycle();bitmap=resized;}int[] rgb=new int[w*h];bitmap.getPixels(rgb,0,w,0,0,w,h);bitmap.recycle();bitmap=null;Pixels out=new Pixels(w,h);for(int row=0;row<h;row++){cancel.check();for(int col=0;col<w;col++){int color=rgb[row*w+col],r=(color>>16)&255,g=(color>>8)&255,b=color&255;out.y[row*w+col]=(byte)clamp(((66*r+129*g+25*b+128)>>8)+16);}}for(int row=0;row<h;row+=2){cancel.check();for(int col=0;col<w;col+=2){int r=0,g=0,b=0;for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++){int color=rgb[(row+dy)*w+col+dx];r+=(color>>16)&255;g+=(color>>8)&255;b+=color&255;}r/=4;g/=4;b/=4;int i=row/2*(w/2)+col/2;out.u[i]=(byte)clamp(((-38*r-74*g+112*b+128)>>8)+128);out.v[i]=(byte)clamp(((112*r-94*g-18*b+128)>>8)+128);}}return out;}catch(RuntimeException|OutOfMemoryError e){throw new IOException("Não foi possível preparar a imagem para o vídeo",e);}finally{if(bitmap!=null)bitmap.recycle();}}
 static int clamp(int v){return Math.max(0,Math.min(255,v));}
 static void plane(Image.Plane plane,byte[] data,int width,int height){ByteBuffer buffer=plane.getBuffer();int rowStride=plane.getRowStride(),pixelStride=plane.getPixelStride();for(int row=0;row<height;row++){if(pixelStride==1){buffer.position(row*rowStride);buffer.put(data,row*width,width);}else for(int col=0;col<width;col++)buffer.put(row*rowStride+col*pixelStride,data[row*width+col]);}}
 static void encode(Pixels picture,long duration,File output,DownloadMux.Cancel cancel)throws IOException{MediaCodec codec=null;try(PhotoCodecOutput sink=new PhotoCodecOutput(output)){MediaFormat format=MediaFormat.createVideoFormat("video/avc",picture.width,picture.height);format.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible);format.setInteger(MediaFormat.KEY_BIT_RATE,2000000);format.setInteger(MediaFormat.KEY_FRAME_RATE,2);format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,5);codec=MediaCodec.createEncoderByType("video/avc");codec.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();long frames=Math.max(1,(duration+FRAME_US-1)/FRAME_US),frame=0,last=SystemClock.elapsedRealtime();boolean ended=false;while(!sink.ended){cancel.check();if(SystemClock.elapsedRealtime()-last>30000)throw new IOException("O codec de vídeo parou de responder");if(!ended){int index=codec.dequeueInputBuffer(10000);if(index>=0){if(frame>=frames){codec.queueInputBuffer(index,0,0,frames*FRAME_US,MediaCodec.BUFFER_FLAG_END_OF_STREAM);ended=true;}else{Image input=codec.getInputImage(index);if(input==null||input.getPlanes().length!=3)throw new IOException("O codificador não aceita imagens YUV compatíveis");Image.Plane[] planes=input.getPlanes();plane(planes[0],picture.y,picture.width,picture.height);plane(planes[1],picture.u,picture.width/2,picture.height/2);plane(planes[2],picture.v,picture.width/2,picture.height/2);ByteBuffer buffer=codec.getInputBuffer(index);int size=buffer==null?picture.width*picture.height*3/2:buffer.capacity();codec.queueInputBuffer(index,0,size,frame*FRAME_US,0);frame++;}last=SystemClock.elapsedRealtime();}}if(sink.drain(codec,cancel))last=SystemClock.elapsedRealtime();}sink.finish();}catch(RuntimeException e){throw new IOException("Não foi possível criar o vídeo H.264 neste aparelho",e);}finally{PhotoCodecOutput.release(codec);}}
}
